package com.example.starter.payment.domain;

/**
 * 交易入账状态。
 * POSTED：已归入某开放批次并计入清算；
 * SUSPENDED：到达时目标批次已封账，挂账待调账。
 */
public enum TxnStatus {
    POSTED,
    SUSPENDED
}

package com.example.starter.payment.domain;

/**
 * 批次状态。OPEN：开放入账；CLOSED：已封账（终态），封账后清算单不可重算。
 */
public enum BatchStatus {
    OPEN,
    CLOSED
}

package com.example.starter.payment.domain;

/**
 * 对账差异类型。
 * LOCAL_EXTRA：本地有账、渠道无账（本地多账）；
 * CHANNEL_EXTRA：渠道有账、本地无账（渠道多账）；
 * AMOUNT_MISMATCH：双方都有但金额不一致（差错）。
 */
public enum DiffType {
    LOCAL_EXTRA,
    CHANNEL_EXTRA,
    AMOUNT_MISMATCH
}

package com.example.starter.payment.domain;

/**
 * 对账差异处理状态。OPEN：待处理；RESOLVED：已处理（核销/补记/退款），不可重复处理。
 */
public enum DiffStatus {
    OPEN,
    RESOLVED
}

package com.example.starter.payment.domain;

/**
 * 差异处理方式。
 * WRITE_OFF：核销（本地多账冲销）；
 * SUPPLEMENT：补记（渠道多账补登本地）；
 * REFUND：退款（金额差错退款）。
 */
public enum ResolveAction {
    WRITE_OFF,
    SUPPLEMENT,
    REFUND
}

package com.example.starter.payment.support;

import org.springframework.http.HttpStatus;

/**
 * 业务异常：由全局异常处理器映射为指定 HTTP 状态码与错误消息。
 */
public class BusinessException extends RuntimeException {

    private final HttpStatus status;

    public BusinessException(HttpStatus status, String message) {
        super(message);
        this.status = status;
    }

    public HttpStatus getStatus() {
        return status;
    }
}

