package com.example.starter.payment.support;

import java.time.Instant;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.time.ZoneOffset;

/**
 * UTC 16:00 日切归属计算。
 * 交易时刻早于 16:00 归入当日批次；达到或晚于 16:00（含 16:00:00 整点）归入次日批次。
 */
public final class Cutoffs {

    /** 日切时刻：UTC 每日 16:00。 */
    public static final int CUTOFF_HOUR = 16;

    private Cutoffs() {
    }

    /**
     * 计算交易时刻所属批次日。
     *
     * @param occurTime 交易发生时刻（UTC）
     * @return 批次归属日（UTC）
     */
    public static LocalDate batchDate(Instant occurTime) {
        LocalDateTime utc = LocalDateTime.ofInstant(occurTime, ZoneOffset.UTC);
        if (utc.getHour() >= CUTOFF_HOUR) {
            return utc.toLocalDate().plusDays(1);
        }
        return utc.toLocalDate();
    }
}

package com.example.starter.payment.dto;

import java.math.BigDecimal;
import java.time.Instant;

import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;

/**
 * 渠道交易入账请求。
 *
 * @param requestId       入账幂等号（非空）
 * @param channelSerialNo 渠道流水号（非空，批次内去重）
 * @param merchantNo      商户号（非空）
 * @param amount          交易金额（元，大于 0）
 * @param occurTime       交易发生时刻（UTC，ISO-8601），为空时取服务当前时间
 */
public record PaymentRequest(
        @NotBlank(message = "requestId 不能为空")
        String requestId,
        @NotBlank(message = "channelSerialNo 不能为空")
        String channelSerialNo,
        @NotBlank(message = "merchantNo 不能为空")
        String merchantNo,
        @NotNull(message = "amount 不能为空")
        @DecimalMin(value = "0.01", message = "amount 必须大于 0")
        BigDecimal amount,
        Instant occurTime) {
}

package com.example.starter.payment.dto;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 入账结果。status：POSTED 已入账 / SUSPENDED 已挂账；replayed 表示命中幂等返回首次结果。
 */
public record PaymentResponse(
        String requestId,
        String channelSerialNo,
        String merchantNo,
        BigDecimal amount,
        Instant occurTime,
        String batchDate,
        String status,
        boolean replayed) {
}

package com.example.starter.payment.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 挂账调账指令：将指定流水的挂账交易在同一事务内转入下一开放批次。
 */
public record AdjustRequest(
        @NotBlank(message = "channelSerialNo 不能为空")
        String channelSerialNo,
        String operator,
        String remark) {
}

package com.example.starter.payment.dto;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 调账结果；fromBatchDate 为已封账批次，toBatchDate 为入账的开放批次。
 */
public record AdjustResponse(
        String channelSerialNo,
        String fromBatchDate,
        String toBatchDate,
        BigDecimal amount,
        Instant adjustedAt) {
}

package com.example.starter.payment.dto;

import java.math.BigDecimal;

/**
 * 单个商户清算结果。settledAmount = totalAmount - totalFee。
 */
public record SettlementItem(
        String merchantNo,
        int txnCount,
        BigDecimal totalAmount,
        BigDecimal totalFee,
        BigDecimal settledAmount) {
}

package com.example.starter.payment.dto;

import java.util.List;

/**
 * 批次封账/清算结果。replayed=true 表示批次已封账，返回首次清算单且未重新计算。
 */
public record SettlementResponse(
        String batchDate,
        String status,
        boolean replayed,
        List<SettlementItem> items) {
}

